 18		"github.com/go-git/go-git/v6/storage/filesystem/dotgit"
 19	)
 20	
 21	const gitDir = ".git"
 22	
 23	// sharedObjectCache is one process-wide object cache. go-git uses the cache
 24	// passed to the storage as its delta-base cache, so a per-open cache makes
 25	// every open re-read pack data from scratch.
 26	var sharedObjectCache = cache.NewObjectLRUDefault()
 27	
 28	// OpenCurrent opens the current git worktree with object alternates enabled.
 29	// The caller owns the returned repository and must close it.
 30	//
 31	// A worktree root that will not resolve is an error, not a reason to open the
 32	// current directory. This used to fall back to ".", which is a different
 33	// repository whenever the two disagree, and go-git disagrees with git in exactly
 34	// the cases that made the resolution fail:
 35	//
 36	//   - git exports GIT_DIR and GIT_WORK_TREE to the hooks it runs, and
 37	//     paths.WorktreeRoot honours them. OpenPath(".") cannot see them, so a hook
 38	//     running for repo A whose git lookup failed opened repo B, the unrelated
 39	//     repository it happened to be sitting in. Verified.
 40	//   - git refuses a repository whose ownership fails its safe.directory check,
 41	//     and refuses a .git it cannot parse. go-git applies neither check, so the
 42	//     fallback opened repositories the user's own git declines to touch.
 43	//
 44	// Five of the six callers write through the repository they are handed, and all
 45	// five sit behind the root pre-run, which already refuses to run when the
 46	// worktree root does not resolve — so this closes a trap rather than a live bug.
 47	// The sixth is a best-effort advisory that genuinely wants the old behaviour and
 48	// now asks for it by name: see OpenCurrentOrCwd.
 49	func OpenCurrent(ctx context.Context) (*git.Repository, error) {
 50		repoRoot, err := paths.WorktreeRoot(ctx)
 51		if err != nil {
 52			return nil, fmt.Errorf("resolve worktree root: %w", err)
 53		}
 54		return OpenPath(repoRoot)
 55	}
 56	
 57	// OpenCurrentOrCwd is OpenCurrent with the current directory as a fallback when
 58	// the worktree root will not resolve.
 59	//
 60	// It exists for one caller, WarnCheckpointPolicyIfNeeded, and the properties
 61	// that make it acceptable there do not generalise: it is dispatched from
 62	// main.go after cobra has finished, so unlike every other repository open it has
 63	// no pre-run guard in front of it; it only READS a policy ref to decide whether
 64	// to print an advisory line; and it discards every error it gets. Opening the
 65	// wrong repository there costs a warning that is skipped or shown, not a write
 66	// that lands in the wrong place.
 67	//
 68	// Do not reach for this because OpenCurrent started returning an error. That
 69	// error means Entire could not establish which repository this is, and for
 70	// anything that writes, stopping is the whole point.
 71	func OpenCurrentOrCwd(ctx context.Context) (*git.Repository, error) {
 72		if repo, err := OpenCurrent(ctx); err == nil {
 73			return repo, nil
 74		}
 75		return OpenPath(".")
 76	}
 77	
 78	// OpenPath opens a git repository with object alternates enabled.
 79	// The caller owns the returned repository and must close it.
 80	func OpenPath(repoRoot string) (*git.Repository, error) {
 81		repoRoot, err := filepath.Abs(repoRoot)
 82		if err != nil {
 83			return nil, fmt.Errorf("resolve repository root: %w", err)
 84		}
 85		repoRoot = filepath.Clean(repoRoot)
 86	
 87		metadata, err := ResolveWorktreeMetadata(repoRoot)
 88		if err != nil {
 89			if errors.Is(err, ErrWorktreeMetadataNotFound) {
 90				repo, bareErr := openBareRepository(repoRoot)
 91				if bareErr == nil {
 92					return repo, nil
 93				}
 94				return nil, fmt.Errorf(
 95					"failed to open repository at %s: worktree metadata: %w; bare repository validation: %w",
 96					repoRoot,
 97					err,
 98					bareErr,
 99				)
100			}
101			return nil, fmt.Errorf("failed to open repository: resolve worktree metadata: %w", err)
102		}
103	
104		repo, err := openWorktreeRepository(repoRoot, metadata)
105		if err == nil {
106			return repo, nil
107		}
108	
109		hasAlternates, alternatesErr := hasObjectAlternates(metadata)
110		if alternatesErr != nil {
111			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", alternatesErr)
112		}
113		usesReftable, reftableErr := inspectRepoUsesReftable(metadata.GitDir, metadata.CommonDir)
114		if reftableErr != nil {
115			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", reftableErr)
116		}
117		if hasAlternates || usesReftable {
118			return nil, fmt.Errorf("failed to open repository with specialized storage: %w", err)
119		}
120	
121		// PlainOpen is safe only after complete metadata validation and positive
122		// evidence that neither specialized storage feature is present.
123		if fallbackRepo, fallbackErr := git.PlainOpen(repoRoot); fallbackErr == nil {
124			return fallbackRepo, nil
125		}
126		return nil, fmt.Errorf("failed to open repository: %w", err)
127	}
128	
129	// ResolveDotGitPath resolves the .git entry for a worktree without opening the
130	// repository. Callers that need Git metadata should use this shared resolver.
131	func ResolveDotGitPath(repoRoot string) (string, error) {
132		return resolveDotGitPath(repoRoot)
133	}
134	
135	// ResolveCommonGitPath resolves the shared Git directory for a resolved .git
136	// directory. An empty result means the repository has no commondir file.
137	func ResolveCommonGitPath(dotGitPath string) (string, error) {
138		return resolveCommonGitPath(dotGitPath)
139	}
