106	func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
107		commonFile := filepath.Join(gitDirPath, "commondir")
108		info, err := os.Lstat(commonFile)
109		if errors.Is(err, fs.ErrNotExist) {
110			return gitDirPath, nil
111		}
112		if err != nil {
113			return "", fmt.Errorf("inspect commondir file at %s: %w", commonFile, err)
114		}
115		if !info.Mode().IsRegular() {
116			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
117		}
118	
119		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
120		if err != nil {
121			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
122		}
123		pointer := strings.TrimRight(string(content), "\r\n")
124		if pointer == "" {
125			return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
126		}
127	
128		resolved := resolveMetadataPath(gitDirPath, pointer)
129		if err := requireMetadataDirectory("common Git directory", resolved); err != nil {
130			return "", err
131		}
132		return filepath.Clean(resolved), nil
133	}
