160	// Preserve the pointer spelling until validation so a missing component cannot
161	// disappear through lexical cleaning before the filesystem sees it.
162	func resolveMetadataPath(base, value string) string {
163		if filepath.IsAbs(value) {
164			return value
165		}
166		return base + string(filepath.Separator) + value
167	}
