 99	// newReftableStorer wraps a filesystem storage with reftable-aware reference
100	// handling. gitDir must be the repository's git directory (for a linked
101	// worktree, the worktree's git dir); git resolves the shared reftable stack
102	// from its commondir automatically.
103	func newReftableStorer(fs *gitfilesystem.Storage, gitDir string) *reftableStorer {
104		return &reftableStorer{Storage: fs, gitDir: gitDir}
105	}
106	
107	// SupportsExtension lets go-git open a repository that declares the
108	// extensions.refstorage=reftable extension, and preserves the embedded
109	// filesystem storage's support for every other extension it recognises
110	// (objectformat=sha1/sha256, worktreeconfig).
111	//
112	// Defining this method here shadows the promoted *gitfilesystem.Storage
113	// method, so it must delegate: without the fallback, a reftable repository
114	// that also declares objectformat=sha256 or worktreeConfig would be rejected
115	// by go-git's extension verification with ErrUnknownExtension, since it only
116	// consults the storer's SupportsExtension. Reftable only changes ref storage,
117	// not object storage, so object-format support is unaffected.
118	func (s *reftableStorer) SupportsExtension(name, value string) bool {
119		if strings.EqualFold(name, "refstorage") {
120			return true
121		}
122		return s.Storage.SupportsExtension(name, value)
123	}
124	
125	// runGit runs a git plumbing command scoped to this repository's git dir and
126	// returns trimmed stdout, raw stderr, and the exec error. Only ref plumbing
127	// (for-each-ref, symbolic-ref, update-ref, rev-parse) is used, none of which
128	// trigger git hooks, so this cannot recurse back into entire. Tests may inject
129	// runGitFn to simulate failures; production dispatches to execGit.
130	func (s *reftableStorer) runGit(args ...string) (string, []byte, error) {
131		if s.runGitFn != nil {
132			return s.runGitFn(args...)
133		}
134		return s.execGit(args...)
135	}
