159	// gitPlumbingEnv builds the environment for a reftable git plumbing command.
160	// LC_ALL=C / LANG=C force untranslated (English) diagnostics so the stderr
161	// classification (isRefCASConflict, and RemoveReference's idempotency check)
162	// stays correct on a localized machine — git's error messages are i18n'd, and
163	// matching translated text would silently misclassify CAS conflicts and delete
164	// failures. GIT_TERMINAL_PROMPT=0 keeps git non-interactive. The forced values
165	// are appended last so they override anything the caller's environment set
166	// (os/exec keeps the last value for a duplicate key). Mirrors the sibling
167	// shell-out in checkpoint/shadow_ref.go.
168	func gitPlumbingEnv() []string {
169		return append(os.Environ(),
170			"GIT_TERMINAL_PROMPT=0",
171			"LC_ALL=C",
172			"LANG=C",
173		)
174	}
