 12	// ErrWorktreeMetadataNotFound reports that an explicit worktree root has no
 13	// .git entry. Repository opening uses it to distinguish a possible bare
 14	// repository from broken worktree metadata.
 15	var ErrWorktreeMetadataNotFound = errors.New("worktree Git metadata not found")
 16	
 17	// WorktreeMetadata contains Git directory facts for one explicit worktree
 18	// root. Paths are cleaned and absolute but retain their lexical spelling.
 19	type WorktreeMetadata struct {
 20		GitDir     string
 21		CommonDir  string
 22		WorktreeID string
 23	}
 24	
 25	// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
 26	// worktree root. It does not discover a root, inspect Git environment
 27	// variables, run Git, cache results, or decide caller policy.
 28	func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
 29		if strings.TrimSpace(worktreeRoot) == "" {
 30			return WorktreeMetadata{}, errors.New("worktree root is required")
 31		}
 32	
 33		root, err := filepath.Abs(worktreeRoot)
 34		if err != nil {
 35			return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
 36		}
 37		root = filepath.Clean(root)
 38		if err := requireMetadataDirectory("worktree root", root); err != nil {
 39			return WorktreeMetadata{}, err
 40		}
 41	
 42		gitDirPath, err := resolveWorktreeGitDir(root)
 43		if err != nil {
 44			return WorktreeMetadata{}, err
 45		}
 46		commonDir, err := resolveWorktreeCommonDir(gitDirPath)
 47		if err != nil {
 48			return WorktreeMetadata{}, err
 49		}
 50		worktreeID, err := resolveWorktreeID(gitDirPath, commonDir)
 51		if err != nil {
 52			return WorktreeMetadata{}, err
 53		}
 54	
 55		return WorktreeMetadata{
 56			GitDir:     gitDirPath,
 57			CommonDir:  commonDir,
 58			WorktreeID: worktreeID,
 59		}, nil
 60	}
 61	
 62	func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
 63		gitEntry := filepath.Join(worktreeRoot, gitDir)
 64		info, err := os.Lstat(gitEntry)
 65		if errors.Is(err, fs.ErrNotExist) {
 66			if rootErr := requireMetadataDirectory("worktree root", worktreeRoot); rootErr != nil {
 67				return "", rootErr
 68			}
 69			return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
 70		}
 71		if err != nil {
 72			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
 73		}
 74		if info.Mode()&fs.ModeSymlink != 0 {
 75			info, err = os.Stat(gitEntry)
 76			if err != nil {
 77				return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
 78			}
 79		}
 80		if info.IsDir() {
 81			return gitEntry, nil
 82		}
 83		if !info.Mode().IsRegular() {
 84			return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
 85		}
 86	
 87		content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
 88		if err != nil {
 89			return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
 90		}
 91		pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
 92		if !ok {
 93			return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
 94		}
 95		if pointer == "" {
 96			return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
 97		}
 98	
 99		resolved := resolveMetadataPath(worktreeRoot, pointer)
100		if err := requireMetadataDirectory("Git directory", resolved); err != nil {
101			return "", err
102		}
103		return filepath.Clean(resolved), nil
104	}
105	
106	func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
107		commonFile := filepath.Join(gitDirPath, "commondir")
108		info, err := os.Lstat(commonFile)
109		if errors.Is(err, fs.ErrNotExist) {
110			return gitDirPath, nil
111		}
112		if err != nil {
113			return "", fmt.Errorf("inspect commondir file at %s: %w", commonFile, err)
114		}
115		if !info.Mode().IsRegular() {
116			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
117		}
118	
119		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
120		if err != nil {
121			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
122		}
123		pointer := strings.TrimRight(string(content), "\r\n")
124		if pointer == "" {
125			return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
126		}
127	
128		resolved := resolveMetadataPath(gitDirPath, pointer)
129		if err := requireMetadataDirectory("common Git directory", resolved); err != nil {
130			return "", err
131		}
132		return filepath.Clean(resolved), nil
133	}
134	
135	func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
136		same, err := metadataDirectoriesIdentifySameFile(gitDirPath, commonDir)
137		if err != nil {
138			return "", fmt.Errorf("compare Git and common directories: %w", err)
139		}
140		if same {
141			return "", nil
142		}
143	
144		registrationRoot := filepath.Join(commonDir, "worktrees")
145		same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(gitDirPath), registrationRoot)
146		if err != nil {
147			return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
148		}
149		if !same {
150			return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
151		}
152	
153		id := filepath.Base(gitDirPath)
154		if id == "." || id == string(filepath.Separator) || id == "" {
155			return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
156		}
157		return id, nil
158	}
159	
160	// Preserve the pointer spelling until validation so a missing component cannot
161	// disappear through lexical cleaning before the filesystem sees it.
162	func resolveMetadataPath(base, value string) string {
163		if filepath.IsAbs(value) {
164			return value
165		}
166		return base + string(filepath.Separator) + value
167	}
168	
169	func requireMetadataDirectory(label, path string) error {
170		info, err := os.Stat(path) //nolint:gosec // the explicit-root API resolves caller-selected repository metadata.
171		if err != nil {
172			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
173		}
174		if !info.IsDir() {
175			return fmt.Errorf("%s at %s is not a directory", label, path)
176		}
177		return nil
178	}
179	
180	func metadataDirectoriesIdentifySameFile(a, b string) (bool, error) {
181		aInfo, err := os.Stat(a)
182		if err != nil {
183			return false, fmt.Errorf("inspect %s: %w", a, err)
184		}
185		if !aInfo.IsDir() {
186			return false, fmt.Errorf("%s is not a directory", a)
187		}
188		bInfo, err := os.Stat(b)
189		if err != nil {
190			return false, fmt.Errorf("inspect %s: %w", b, err)
191		}
192		if !bInfo.IsDir() {
193			return false, fmt.Errorf("%s is not a directory", b)
194		}
195		return os.SameFile(aInfo, bInfo), nil
196	}
