158	func hasObjectAlternates(metadata WorktreeMetadata) (bool, error) {
159		candidates := []string{filepath.Join(metadata.GitDir, "objects", "info", "alternates")}
160		if metadata.CommonDir != metadata.GitDir {
161			candidates = append(candidates, filepath.Join(metadata.CommonDir, "objects", "info", "alternates"))
162		}
163		for _, candidate := range candidates {
164			info, err := os.Lstat(candidate)
165			if err == nil {
166				if info.Mode()&os.ModeSymlink != 0 {
167					if _, err := os.Stat(candidate); err != nil {
168						return false, fmt.Errorf("inspect alternates file: %w", err)
169					}
170				}
171				return true, nil
172			}
173			if !errors.Is(err, os.ErrNotExist) {
174				return false, fmt.Errorf("inspect alternates file: %w", err)
175			}
176		}
177		return false, nil
178	}
