235	func resolveDotGitPath(repoRoot string) (string, error) {
236		gitPath := filepath.Join(repoRoot, gitDir)
237		info, err := os.Stat(gitPath)
238		if err != nil {
239			return "", fmt.Errorf("stat .git path: %w", err)
240		}
241		if info.IsDir() {
242			return gitPath, nil
243		}
244	
245		content, err := os.ReadFile(gitPath) //nolint:gosec // gitPath is resolved from the git worktree root.
246		if err != nil {
247			return "", fmt.Errorf("read .git file: %w", err)
248		}
249	
250		line, _, _ := strings.Cut(string(content), "\n")
251		gitdir, ok := strings.CutPrefix(strings.TrimSpace(line), "gitdir:")
252		if !ok {
253			return "", errors.New(".git file has no gitdir prefix")
254		}
255	
256		gitdir = strings.TrimSpace(gitdir)
257		if filepath.IsAbs(gitdir) {
258			return filepath.Clean(gitdir), nil
259		}
260		return filepath.Clean(filepath.Join(repoRoot, gitdir)), nil
261	}
262	
263	func resolveCommonGitPath(dotGitPath string) (string, error) {
264		content, err := os.ReadFile(filepath.Join(dotGitPath, "commondir")) //nolint:gosec // dotGitPath is resolved from the git worktree root.
265		if errors.Is(err, os.ErrNotExist) {
266			return "", nil
267		}
268		if err != nil {
269			return "", fmt.Errorf("read commondir file: %w", err)
270		}
271	
272		commonPath := strings.TrimSpace(string(content))
273		if commonPath == "" {
274			return "", nil
275		}
276		if filepath.IsAbs(commonPath) {
277			return filepath.Clean(commonPath), nil
278		}
279		return filepath.Clean(filepath.Join(dotGitPath, commonPath)), nil
280	}
