137	func (s *reftableStorer) execGit(args ...string) (string, []byte, error) {
138		ctx, cancel := context.WithTimeout(context.Background(), reftableGitTimeout)
139		defer cancel()
140	
141		full := append([]string{"--git-dir", s.gitDir}, args...)
142		cmd := exec.CommandContext(ctx, "git", full...)
143		cmd.Env = gitPlumbingEnv()
144	
145		var stdout, stderr bytes.Buffer
146		cmd.Stdout = &stdout
147		cmd.Stderr = &stderr
148		err := cmd.Run()
149		// On our timeout the process is killed and Run reports the kill as an
150		// *exec.ExitError, which would be indistinguishable from a genuine
151		// non-zero exit. Re-wrap with the context error so callers (refLookupAbsent)
152		// never mistake a wedged git for a definitive "ref not found".
153		if err != nil && ctx.Err() != nil {
154			err = fmt.Errorf("git %s timed out after %s: %w", strings.Join(args, " "), reftableGitTimeout, ctx.Err())
155		}
156		return strings.TrimRight(stdout.String(), "\n"), stderr.Bytes(), err
157	}
