176	// refLookupAbsent reports whether a failed ref lookup (rev-parse --verify
177	// --quiet, update-ref) means the reference is genuinely absent rather than a
178	// failure to consult git at all. Only genuine absence may map to the
179	// plumbing.ErrReferenceNotFound / idempotent-delete sentinels; a spawn failure,
180	// timeout, or I/O error must be surfaced so a transient git failure is never
181	// mistaken for a missing ref (which would let the strategy orphan a checkpoint
182	// ref or drop a link).
183	//
184	// git ran and reported absence iff it exited non-zero AND stayed silent: under
185	// --quiet a missing ref produces no error output, whereas a fatal/I/O failure
186	// exits non-zero with a "fatal: ..." message, and a spawn failure or our
187	// timeout is not an *exec.ExitError at all.
188	func refLookupAbsent(err error, stderr []byte) bool {
189		if err == nil {
190			return false
191		}
192		if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
193			return false
194		}
195		var exitErr *exec.ExitError
196		if !errors.As(err, &exitErr) {
197			return false
198		}
199		return len(bytes.TrimSpace(stderr)) == 0
200	}
