 28	// OpenCurrent opens the current git worktree with object alternates enabled.
 29	// The caller owns the returned repository and must close it.
 30	//
 31	// A worktree root that will not resolve is an error, not a reason to open the
 32	// current directory. This used to fall back to ".", which is a different
 33	// repository whenever the two disagree, and go-git disagrees with git in exactly
 34	// the cases that made the resolution fail:
 35	//
 36	//   - git exports GIT_DIR and GIT_WORK_TREE to the hooks it runs, and
 37	//     paths.WorktreeRoot honours them. OpenPath(".") cannot see them, so a hook
 38	//     running for repo A whose git lookup failed opened repo B, the unrelated
 39	//     repository it happened to be sitting in. Verified.
 40	//   - git refuses a repository whose ownership fails its safe.directory check,
 41	//     and refuses a .git it cannot parse. go-git applies neither check, so the
 42	//     fallback opened repositories the user's own git declines to touch.
 43	//
 44	// Five of the six callers write through the repository they are handed, and all
 45	// five sit behind the root pre-run, which already refuses to run when the
 46	// worktree root does not resolve — so this closes a trap rather than a live bug.
 47	// The sixth is a best-effort advisory that genuinely wants the old behaviour and
 48	// now asks for it by name: see OpenCurrentOrCwd.
 49	func OpenCurrent(ctx context.Context) (*git.Repository, error) {
 50		repoRoot, err := paths.WorktreeRoot(ctx)
 51		if err != nil {
 52			return nil, fmt.Errorf("resolve worktree root: %w", err)
 53		}
 54		return OpenPath(repoRoot)
 55	}
 56	
 57	// OpenCurrentOrCwd is OpenCurrent with the current directory as a fallback when
 58	// the worktree root will not resolve.
 59	//
 60	// It exists for one caller, WarnCheckpointPolicyIfNeeded, and the properties
 61	// that make it acceptable there do not generalise: it is dispatched from
 62	// main.go after cobra has finished, so unlike every other repository open it has
 63	// no pre-run guard in front of it; it only READS a policy ref to decide whether
 64	// to print an advisory line; and it discards every error it gets. Opening the
 65	// wrong repository there costs a warning that is skipped or shown, not a write
 66	// that lands in the wrong place.
 67	//
 68	// Do not reach for this because OpenCurrent started returning an error. That
 69	// error means Entire could not establish which repository this is, and for
 70	// anything that writes, stopping is the whole point.
 71	func OpenCurrentOrCwd(ctx context.Context) (*git.Repository, error) {
 72		if repo, err := OpenCurrent(ctx); err == nil {
 73			return repo, nil
 74		}
 75		return OpenPath(".")
 76	}
