 78	// OpenPath opens a git repository with object alternates enabled.
 79	// The caller owns the returned repository and must close it.
 80	func OpenPath(repoRoot string) (*git.Repository, error) {
 81		repoRoot, err := filepath.Abs(repoRoot)
 82		if err != nil {
 83			return nil, fmt.Errorf("resolve repository root: %w", err)
 84		}
 85		repoRoot = filepath.Clean(repoRoot)
 86	
 87		metadata, err := ResolveWorktreeMetadata(repoRoot)
 88		if err != nil {
 89			if errors.Is(err, ErrWorktreeMetadataNotFound) {
 90				repo, bareErr := openBareRepository(repoRoot)
 91				if bareErr == nil {
 92					return repo, nil
 93				}
 94				return nil, fmt.Errorf(
 95					"failed to open repository at %s: worktree metadata: %w; bare repository validation: %w",
 96					repoRoot,
 97					err,
 98					bareErr,
 99				)
100			}
101			return nil, fmt.Errorf("failed to open repository: resolve worktree metadata: %w", err)
102		}
103	
104		repo, err := openWorktreeRepository(repoRoot, metadata)
105		if err == nil {
106			return repo, nil
107		}
108	
109		hasAlternates, alternatesErr := hasObjectAlternates(metadata)
110		if alternatesErr != nil {
111			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", alternatesErr)
112		}
113		usesReftable, reftableErr := inspectRepoUsesReftable(metadata.GitDir, metadata.CommonDir)
114		if reftableErr != nil {
115			return nil, fmt.Errorf("inspect repository after specialized open failed: %w", reftableErr)
116		}
117		if hasAlternates || usesReftable {
118			return nil, fmt.Errorf("failed to open repository with specialized storage: %w", err)
119		}
120	
121		// PlainOpen is safe only after complete metadata validation and positive
122		// evidence that neither specialized storage feature is present.
123		if fallbackRepo, fallbackErr := git.PlainOpen(repoRoot); fallbackErr == nil {
124			return fallbackRepo, nil
125		}
126		return nil, fmt.Errorf("failed to open repository: %w", err)
127	}
