129	// ResolveDotGitPath resolves the .git entry for a worktree without opening the
130	// repository. Callers that need Git metadata should use this shared resolver.
131	func ResolveDotGitPath(repoRoot string) (string, error) {
132		return resolveDotGitPath(repoRoot)
133	}
