 21	// reftableGitTimeout bounds each git plumbing invocation the reftable storer
 22	// makes. Ref reads/writes against the local reftable stack are fast; the
 23	// timeout only guards against a wedged git process.
 24	const reftableGitTimeout = 30 * time.Second
 25	
 26	// inspectRepoUsesReftable reports whether the repository at the given git directories
 27	// stores its references using the reftable backend rather than the classic
 28	// loose-files + packed-refs layout.
 29	//
 30	// go-git (through the vendored v6 alpha) has no reftable reader: its filesystem
 31	// storer reads refs from .git/refs, .git/packed-refs and .git/HEAD, none of
 32	// which are authoritative in a reftable repository. Detection lets us route ref
 33	// operations through the git CLI instead (see reftableStorer).
 34	//
 35	// A reftable repository is identified by the presence of a "reftable/"
 36	// directory under either the worktree git dir or the common git dir. Git 2.45+
 37	// creates this directory for `git init --ref-format=reftable` and for
 38	// `git refs migrate --ref-format=reftable`. Checking the directory avoids
 39	// parsing config and works for linked worktrees, where the shared stack lives
 40	// under the common git dir.
 41	func inspectRepoUsesReftable(dotGitPath, commonGitPath string) (bool, error) {
 42		candidates := []string{filepath.Join(dotGitPath, "reftable")}
 43		if commonGitPath != "" && commonGitPath != dotGitPath {
 44			candidates = append(candidates, filepath.Join(commonGitPath, "reftable"))
 45		}
 46		for _, dir := range candidates {
 47			// Lstat, not Stat: git creates reftable/ as a real directory, so a
 48			// symlink in its place is not a genuine reftable stack. Lstat inspects
 49			// the entry itself rather than following the link, so a symlink reports
 50			// IsDir()==false and is correctly not treated as a reftable repository.
 51			info, err := os.Lstat(dir)
 52			if err == nil {
 53				if info.IsDir() {
 54					return true, nil
 55				}
 56				continue
 57			}
 58			if !errors.Is(err, os.ErrNotExist) {
 59				return false, fmt.Errorf("inspect reftable directory %s: %w", dir, err)
 60			}
 61		}
 62		return false, nil
 63	}
 64	
 65	// reftableStorer adapts a filesystem-backed go-git storage so it can open and
 66	// operate on repositories that use the reftable ref backend. Object, config,
 67	// index, shallow and module storage keep flowing through the embedded
 68	// filesystem storage (reftable only changes ref storage, not object storage);
 69	// the reference-storer methods are overridden to shell out to the git CLI,
 70	// which is the only reftable reader/writer available to us.
 71	//
 72	// It also advertises reftable support via the ExtensionChecker interface so
 73	// go-git's extension verification does not reject the repository on open.
 74	//
 75	// TODO: remove this entire type (and its wiring in repository.go) once go-git
 76	// gains a built-in reftable reader/writer. It exists only because the vendored
 77	// go-git has no reftable backend, so ref operations must shell out to the git
 78	// CLI. When upstream supports reftable natively, the plain filesystem storer
 79	// handles these repositories and this shim can be deleted.
 80	type reftableStorer struct {
 81		*gitfilesystem.Storage
 82	
 83		gitDir string
 84	
 85		// runGitFn runs a git plumbing command and returns trimmed stdout, raw
 86		// stderr, and the exec error. It is overridable in tests to simulate
 87		// spawn/timeout/exit failures deterministically; in production it is nil and
 88		// runGit dispatches to execGit.
 89		runGitFn func(args ...string) (string, []byte, error)
 90	}
 91	
 92	var (
 93		_ gogitstorage.Storer = (*reftableStorer)(nil)
 94		// The concrete methods below satisfy storer.ReferenceStorer, overriding the
 95		// embedded filesystem implementation.
 96		_ storer.ReferenceStorer = (*reftableStorer)(nil)
 97	)
 98	
 99	// newReftableStorer wraps a filesystem storage with reftable-aware reference
100	// handling. gitDir must be the repository's git directory (for a linked
101	// worktree, the worktree's git dir); git resolves the shared reftable stack
102	// from its commondir automatically.
103	func newReftableStorer(fs *gitfilesystem.Storage, gitDir string) *reftableStorer {
104		return &reftableStorer{Storage: fs, gitDir: gitDir}
105	}
106	
107	// SupportsExtension lets go-git open a repository that declares the
108	// extensions.refstorage=reftable extension, and preserves the embedded
109	// filesystem storage's support for every other extension it recognises
110	// (objectformat=sha1/sha256, worktreeconfig).
111	//
112	// Defining this method here shadows the promoted *gitfilesystem.Storage
