126	// returns trimmed stdout, raw stderr, and the exec error. Only ref plumbing
127	// (for-each-ref, symbolic-ref, update-ref, rev-parse) is used, none of which
128	// trigger git hooks, so this cannot recurse back into entire. Tests may inject
129	// runGitFn to simulate failures; production dispatches to execGit.
130	func (s *reftableStorer) runGit(args ...string) (string, []byte, error) {
