			},
			want: "commondir entry",
		},
		{
			name: "nested registration",
			setup: func(t *testing.T) string {
				root := t.TempDir()
				common := filepath.Join(root, "store")
				perWorktree := filepath.Join(common, "worktrees", "nested", "id")
